INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 1, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, 1, 60000, 1, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 2, 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 3, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 4, 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 0, 2, 60000, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 5, 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 6, 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 7, 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 0, 2, 60000, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 8, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 9, 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 10, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 11, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 12, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 0, 2, 60000, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 13, 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 14, 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 15, 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 16, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 0, 2, 60000, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 17, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 0, 2, 60000, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 18, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, 3, 60000, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 19, 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, 3, 60000, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 20, 1, "キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", 101201, 0, 80001, 0, "ハツネ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 21, 1, "少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", 101201, 0, 80001, 0, "ハツネ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 22, 1, "あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", 103801, 1, 80001, 0, "シオリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 23, 1, "来年も、\n一緒にいられたら…\nうれしいな", 103801, 1, 80001, 0, "シオリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 24, 2, "あなたと一緒にいるようになって、\nもう1年ですか…", 103601, 0, 80001, 0, "キョウカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 25, 2, "最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", 103601, 0, 80001, 0, "キョウカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 26, 2, "おにいちゃんとあってから、\n1年たったよ～！", 102001, 1, 80001, 0, "ミミ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 27, 2, "ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", 102001, 1, 80001, 0, "ミミ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 28, 2, "にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", 100401, 2, 80001, 0, "ミソギ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 29, 2, "…これからもいっぱいミソギと\n遊んでね、にいちゃん！", 100401, 2, 80001, 0, "ミソギ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 30, 3, "もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", 101001, 0, 80001, 0, "マホ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 31, 3, "このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", 101001, 0, 80001, 0, "マホ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 32, 3, "お主と会って早1年じゃな\nこれからも存分に尽くすがよい", 104401, 1, 80001, 0, "イリヤ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 33, 3, "わらわもたまには、お主の献身に\n報いてやらぬでもない♪", 104401, 1, 80001, 0, "イリヤ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 34, 3, "もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", 101701, 2, 80001, 0, "カオリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 35, 3, "これからも、どうぞよろしく\nお願いするさ～！", 101701, 2, 80001, 0, "カオリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 36, 4, "あんたと出会ってからもうそんなに\nたつのね～", 102801, 0, 80001, 0, "サレン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 37, 4, "あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", 102801, 0, 80001, 0, "サレン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 38, 4, "出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", 102501, 1, 80001, 0, "スズメ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 39, 4, "これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", 102501, 1, 80001, 0, "スズメ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 40, 5, "振り返れば、今までいろんなことが\nあったにゃあ…", 104601, 0, 80001, 0, "タマキ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 41, 5, "これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", 104601, 0, 80001, 0, "タマキ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 42, 5, "キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", 104801, 1, 80001, 0, "ミフユ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 43, 5, "まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", 104801, 1, 80001, 0, "ミフユ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 44, 6, "あなたさまと出会ってもう1年…", 103201, 0, 80001, 0, "アキノ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 45, 6, "光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", 103201, 0, 80001, 0, "アキノ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 46, 6, "ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", 103401, 1, 80001, 0, "ユカリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 47, 6, "情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", 103401, 1, 80001, 0, "ユカリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 48, 7, "オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", 107101, 0, 80001, 0, "クリスティーナ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 49, 7, "ともかくこれからも\n愉しませてくれよ☆", 107101, 0, 80001, 0, "クリスティーナ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 50, 7, "君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", 104701, 1, 80001, 0, "ジュン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 51, 7, "見えないから分からないって？\nそれもそうだな…", 104701, 1, 80001, 0, "ジュン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 52, 8, "もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", 103701, 0, 80001, 0, "トモ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 53, 8, "これからもよろしくね！", 103701, 0, 80001, 0, "トモ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 54, 8, "出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", 100501, 1, 80001, 0, "マツリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 55, 8, "毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", 100501, 1, 80001, 0, "マツリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 56, 9, "オマエと会って1年なの！\n全然成仏もできなかったし、", 100701, 0, 80001, 0, "ミヤコ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 57, 9, "生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", 100701, 0, 80001, 0, "ミヤコ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 58, 9, "あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", 103101, 1, 80001, 0, "シノブ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 59, 9, "来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", 103101, 1, 80001, 0, "シノブ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 60, 10, "貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", 100901, 0, 80001, 0, "アンナ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 61, 10, "それでも貴様となら…\n添い遂げる覚悟はできているぞ！", 100901, 0, 80001, 0, "アンナ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 62, 10, "君と出会ってもう1年だって！\n早いねー！", 101301, 1, 80001, 0, "ナナカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 63, 10, "これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", 101301, 1, 80001, 0, "ナナカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 64, 11, "1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", 105101, 0, 80001, 0, "ミツキ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 65, 11, "これからも、いろんなところを\n調べさせてね？", 105101, 0, 80001, 0, "ミツキ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 66, 11, "お前さんと出会ってもう1年か\n助太刀するつもりが", 105601, 1, 80001, 0, "ルカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 67, 11, "逆に助けられたりもしたね\nこれからもよろしく頼むよ！", 105601, 1, 80001, 0, "ルカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 68, 11, "早いものですわね、あなた様と\nお会いして、もう1年…", 102701, 2, 80001, 0, "エリコ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 69, 11, "あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", 102701, 2, 80001, 0, "エリコ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 70, 12, "お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", 102301, 0, 80001, 0, "アヤネ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 71, 12, "あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", 102301, 0, 80001, 0, "アヤネ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 72, 12, "あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", 104201, 1, 80001, 0, "チカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 73, 12, "私のことを見守ってください\nできることなら、ずっと…", 104201, 1, 80001, 0, "チカ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 74, 12, "お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", 102101, 2, 80001, 0, "クルミ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 75, 12, "で、でもこれからもずっと…\n一緒にいたいなぁ…", 102101, 2, 80001, 0, "クルミ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 76, 13, "再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", 104901, 0, 80001, 0, "シズル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 77, 13, "ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", 104901, 0, 80001, 0, "シズル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 78, 13, "お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", 101101, 1, 80001, 0, "リノ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 79, 13, "信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", 101101, 1, 80001, 0, "リノ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 80, 14, "騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", 100201, 0, 80001, 0, "ユイ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 81, 14, "そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", 100201, 0, 80001, 0, "ユイ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 82, 14, "騎士くんと出会って、まだ1年しか\nたってないんだ！？", 100101, 1, 80001, 0, "ヒヨリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 83, 14, "なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", 100101, 1, 80001, 0, "ヒヨリ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 84, 14, "初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", 100301, 2, 80001, 0, "レイ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 85, 14, "キミに背中を預けられる日が、\n早くきますように", 100301, 2, 80001, 0, "レイ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 86, 15, "1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", 105801, 0, 80001, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 87, 15, "これからもずっと、覚えていて\nくださいね！", 105801, 0, 80001, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 88, 15, "こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", 105901, 1, 80001, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 89, 15, "末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", 105901, 1, 80001, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 90, 15, "1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", 106001, 2, 80001, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 91, 15, "だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", 106001, 2, 80001, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 92, 0, "新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", 112101, 1, 60001, 1, "スズメ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 93, 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 94, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 95, 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 96, 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 97, 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 0, 2, 60001, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 98, 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 99, 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 100, 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 101, 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 102, 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 0, 2, 60001, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 103, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 104, 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 105, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 106, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 107, 0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 108, 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 109, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 0, 2, 60001, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 110, 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 111, 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 112, 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 113, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 114, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 115, 0, "今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", 0, 2, 60001, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 116, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 0, 2, 60001, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 117, 0, "おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", 112101, 3, 60001, 0, "スズメ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 118, 7, "おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", 112101, 3, 60001, 0, "スズメ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 119, 1, "ヒューヒュー♪\nドンドンパフパフー♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 120, 1, "ひゅーひゅー\nどんどんぱふぱふー\nでございます", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 121, 1, "さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 122, 1, "え？　ちょっと\nいきなりなにっ？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 123, 1, "ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 124, 1, "実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 125, 1, "『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 126, 1, "ですからその日に向けて\n今から気分を盛り上げているのです", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 127, 1, "ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 128, 1, "いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 129, 1, "その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 130, 1, "ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 131, 1, "ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 132, 2, "記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 133, 2, "あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", 190801, 1, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 134, 2, "げっ…カリンじゃない\nなんでもないわよ！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 135, 2, "そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", 190801, 1, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 136, 2, "分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 137, 2, "ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", 190801, 1, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 138, 2, "気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 139, 2, "…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 140, 2, "なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", 190801, 1, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 141, 2, "はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 142, 2, "キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", 190801, 1, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 143, 2, "心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 144, 3, "ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 145, 3, "色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 146, 3, "はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 147, 3, "たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 148, 3, "魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 149, 3, "あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 150, 3, "あとは、牧場に素敵な温泉が\n出来たとか…", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 151, 3, "牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 152, 3, "ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 153, 3, "えへへ、ありがとうございます\nコッコロちゃん！", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 154, 3, "それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 155, 3, "これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", 105801, 1, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 156, 4, "2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 157, 4, "あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 158, 4, "キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 159, 4, "なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 160, 4, "えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 161, 4, "…積極的？\nなんの話よ？", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 162, 4, "またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 163, 4, "ムーサの町で\nきゃるきゃる～ん☆　って！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 164, 4, "あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 165, 4, "本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 166, 4, "まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 167, 4, "ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", 106001, 1, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 168, 5, "2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 169, 5, "そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 170, 5, "やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 171, 5, "キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 172, 5, "な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 173, 5, "そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 174, 5, "お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 175, 5, "ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 176, 5, "かくし芸？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 177, 5, "はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 178, 5, "～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 179, 6, "あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 180, 6, "ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 181, 6, "大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 182, 6, "さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 183, 6, "─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 184, 6, "はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 185, 6, "そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 186, 6, "そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 187, 6, "信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 188, 6, "えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 189, 6, "わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 190, 6, "あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 191, 7, "ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 192, 7, "なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 193, 7, "いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 194, 7, "あー\nあー\n…声、これで大丈夫かしら？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 195, 7, "聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 196, 7, "オイッスー☆", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 197, 7, "……\nいや、ないわ\nいつもどおりが一番ね、うん", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 198, 7, "もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 199, 7, "ど、どど、どうしよう！？\n緊張してきちゃった…！！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 200, 8, "主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 201, 8, "多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 202, 8, "わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 203, 8, "ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 204, 8, "そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 205, 8, "オイッスー☆", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 206, 8, "先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 207, 8, "良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 208, 8, "この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", 105901, 0, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 209, 9, "オイッスー☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 210, 9, "…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 211, 9, "あと６日で2.5周年ですか…", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 212, 9, "この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 213, 9, "生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 214, 9, "オイッスー☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 215, 9, "…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 216, 9, "今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 217, 9, "そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 218, 9, "あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 219, 9, "なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 220, 10, "2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 221, 10, "はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 222, 10, "おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 223, 10, "…………", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 224, 10, "キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 225, 10, "かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 226, 10, "大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 227, 10, "きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 228, 10, "これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 229, 10, "これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 230, 10, "このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 231, 10, "キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 232, 10, "え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 233, 10, "えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 234, 11, "ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 235, 11, "【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 236, 11, "頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 237, 11, "ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 238, 11, "まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 239, 11, "次にコッコロさんですが\nこちらは発声練習をしています", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 240, 11, "一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 241, 11, "そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 242, 11, "あれ？\nもしかして緊張で気を失って…？", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 243, 11, "…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 244, 11, "３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 245, 11, "それでは\nまた明日お会いしましょう♪", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 246, 12, "2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 247, 12, "３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", 105801, 2, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 248, 12, "ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 45, 0, "", 249, 12, "信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 250, 12, "ひどいですよぉキャルちゃ～ん！", 105801, 2, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 251, 12, "ふふ。お二人とも\n普段通りの様子で\n安心いたしました", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 252, 12, "はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", 105801, 2, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 46, 0, "", 253, 12, "そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", 106001, 0, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 254, 12, "わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 255, 12, "それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", 105801, 2, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 256, 13, "えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 47, 0, "", 257, 13, "は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 258, 13, "忘れてきちゃいました☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 48, 0, "", 259, 13, "忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 260, 13, "マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 49, 0, "", 261, 13, "あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 262, 13, "あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 50, 0, "", 263, 13, "え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 264, 13, "キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 51, 0, "", 265, 13, "あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 266, 13, "はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 52, 0, "", 267, 13, "コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 268, 13, "あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 269, 13, "ふふ\nきっと面白い生放送になると\nわたくし、確信しております", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 45, 0, "", 270, 13, "絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 53, 0, "", 271, 13, "そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 46, 0, "", 272, 13, "それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 273, 14, "こんにちは\n【ギルド管理協会】のカリンです", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 274, 14, "昨日の生放送は\nいかがだったでしょうか？", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 275, 14, "たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 276, 14, "そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 277, 14, "【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 278, 14, "【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 279, 14, "…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 280, 14, "この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 281, 14, "きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 282, 14, "それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", 190801, 0, 80003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 47, 0, "", 283, 15, "準備はいいですかっ？\n…いっきますよー！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 54, 0, "", 284, 15, "祝！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 285, 15, "2.5周年！", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 48, 0, "", 286, 15, "おめでとうございま～す☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 55, 0, "", 287, 15, "少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 288, 15, "光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 49, 0, "", 289, 15, "コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 56, 0, "", 290, 15, "ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 291, 15, "ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 57, 0, "", 292, 15, "あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 50, 0, "", 293, 15, "あー！　二人ともずるいです！\nわたしもっ、ギュー♪", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 58, 0, "", 294, 15, "ちょっ、ペコリーヌ！\nくっつき過ぎよ！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 51, 0, "", 295, 15, "記念日だから\n平気平気♪\nやばいですね☆", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 59, 0, "", 296, 15, "意味分かんないわよ！", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 297, 15, "ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 298, 15, "喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 52, 0, "", 299, 15, "さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 60, 0, "", 300, 15, "分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", 106001, 2, 80003, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 301, 15, "ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", 105901, 1, 80003, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 53, 0, "", 302, 15, "はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", 105801, 0, 80003, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 54, 1, "105901,45,106001,61", 303, 15, "2.5周年\nありがとうございます！", 105801, 0, 80003, 0, "ペコリーヌ・コッコロ・キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 304, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, 1, 60002, 1, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 305, 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 306, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 307, 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 308, 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 309, 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 0, 2, 60002, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 310, 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 311, 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 312, 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 313, 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 314, 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 0, 2, 60002, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 315, 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 316, 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 317, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 318, 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 319, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 320, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 321, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", 0, 2, 60002, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 322, 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 323, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 324, 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 325, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 326, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 327, 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 0, 2, 60002, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 328, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 0, 2, 60002, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 329, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, 3, 60002, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 330, 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, 3, 60002, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 331, 1, "ささ、シェフィさまはこちらへ…", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 332, 1, "コッコロさん、どこへ行くの…？\n…え？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 333, 1, "『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 334, 1, "ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 335, 1, "ええと…\n二人とも何をしているの？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 336, 1, "シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 337, 1, "あの日…？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 338, 1, "その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 339, 1, "『プリンセスコネクト！\nRe:Dive』3.5周年！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 340, 1, "やばいですね☆", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 341, 1, "って、なにしれっと\n参加してんのよカリン！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 342, 1, "ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 343, 1, "それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 344, 1, "というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 345, 1, "えっ！？　ええとええと…！\nあ、あと14日…！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 346, 2, "3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 347, 2, "豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 348, 2, "そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 349, 2, "すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 350, 2, "さすがでございます\nペコリーヌさま", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 351, 2, "いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 352, 2, "しゃなり、しゃなり…\nふふ、案外できるものね", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 353, 2, "わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 354, 2, "さ、次はキャルさまの\n番でございますよ", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 355, 2, "あ、あたしはいいわよ！\nそういうの全然分かんないし…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 356, 2, "大丈夫\nやってみると結構楽しいわよ\nほらほらっ", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 357, 2, "そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 358, 2, "いたたた…もぉお～！\nなんであたしがこんな目に～！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 359, 2, "まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 360, 2, "よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 361, 3, "3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 362, 3, "分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 363, 3, "特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 364, 3, "聖学祭…って、なにかしら？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 365, 3, "聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 366, 3, "それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 367, 3, "カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 368, 3, "なかよし部…\n仲が良さそうな名前で\nやばいですね☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 369, 3, "いや、そのまんますぎでしょ…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 370, 3, "聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 371, 3, "それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 372, 3, "えっ？　ええ…\nぎゅーっ…？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 373, 4, "3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 374, 4, "そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 375, 4, "なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 376, 4, "もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 377, 4, "あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 378, 4, "そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 379, 4, "バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 380, 4, "こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 381, 4, "うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 382, 4, "シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 383, 4, "はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 384, 4, "だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 12, 0, "", 385, 4, "みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 386, 5, "3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 387, 5, "そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 388, 5, "学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 389, 5, "暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 390, 5, "だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 391, 5, "キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 392, 5, "乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 393, 5, "キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 394, 5, "う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 395, 5, "あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 396, 5, "そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 397, 5, "乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, 0, "", 398, 6, "3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 5, 0, "", 399, 6, "3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 400, 6, "…えっ！？", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 401, 6, "本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 402, 6, "いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 403, 6, "はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 404, 6, "わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 405, 6, "ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 406, 6, "去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 407, 6, "ぶっ殺すぞ！？", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 6, 0, "", 408, 6, "というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 409, 7, "3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 410, 7, "そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 411, 7, "宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 412, 7, "あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 413, 7, "ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 414, 7, "夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 16, 0, "", 415, 7, "その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 416, 7, "楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 17, 0, "", 417, 7, "もちろんでございます\n仲良くお勉強いたしましょう", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 418, 7, "しれっと教育ママが\n生まれてる…？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 419, 7, "お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 420, 7, "え～～～～！？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 421, 8, "3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 422, 8, "…\nねぇコッコロさん\nキャル、どうしちゃったの？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 18, 0, "", 423, 8, "とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 424, 8, "あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 425, 8, "ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 426, 8, "ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 19, 0, "", 427, 8, "なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 428, 8, "…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 429, 8, "ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 430, 8, "こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 431, 8, "えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 432, 8, "も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 433, 9, "3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 434, 9, "…えっ？\n生放送の意気込み！？\n突然なに！？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 435, 9, "ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 436, 9, "えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 437, 9, "とにかく落ち着いて\nスタッフさんの指示を聞いて…", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 438, 9, "それから、それから…！\nぅ、ぅぅっ…！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 439, 9, "―びえぇぇ～んっ！！！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 20, 0, "", 440, 9, "どうされましたか、シェフィさま", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 441, 9, "ううっ…ひっく…\nママッ…！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 21, 0, "", 442, 9, "よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 22, 0, "", 443, 9, "…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 444, 9, "…ううっ\n恥ずかしすぎて\nもう生放送出られない…", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 23, 0, "", 445, 10, "主さま\n3.5周年まであと５日\nでございます", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 24, 0, "", 446, 10, "ですがその前に\n生放送がありますね", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 25, 0, "", 447, 10, "…生放送に向けた\n意気込みでございますか？", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 448, 10, "もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 449, 10, "…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 450, 10, "ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 451, 10, "どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 452, 10, "それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 453, 10, "主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", 105901, 0, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 26, 0, "", 454, 11, "3.5周年まであと４日！\nやばいですね☆", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 455, 11, "はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 27, 0, "", 456, 11, "ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 28, 0, "", 457, 11, "あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 29, 0, "", 458, 11, "キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 459, 11, "はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 30, 0, "", 460, 11, "もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 461, 11, "こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 462, 11, "オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 463, 11, "だからあたしはやるなんて一言も…", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 464, 11, "オイッスー☆", 105801, 0, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 465, 11, "聞きなさいっての！！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 31, 0, "", 466, 12, "3.5周年まであと３日…\nそして生放送は、明日…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 467, 12, "もっと台本を\n読み込んでおかないと…\nあと発声練習も…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 468, 12, "おいっす！\n…こうじゃなかったわね\nええと確か…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 469, 12, "うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 470, 12, "【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 34, 0, "", 471, 12, "やってますねシェフィちゃん！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 472, 12, "なによ、考えることは\nみんな同じってこと？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 32, 0, "", 473, 12, "ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 474, 12, "みんな…もちろんよ！", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 475, 12, "それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 7, 0, "", 476, 13, "3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 8, 0, "", 477, 13, "【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 478, 13, "今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 9, 0, "", 479, 13, "お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 33, 0, "", 480, 13, "はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 10, 0, "", 481, 13, "さすが【美食殿】のママですね！\nそしてキャルさんは…", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 482, 13, "大丈夫…大丈夫…\nあたしは大丈夫…", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 11, 0, "", 483, 13, "す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 484, 13, "あうー？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 1, "105901,34,106001,38,190801,12", 485, 13, "あ…", 105801, 4, 80005, 0, "みんな");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 486, 13, "ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 35, 0, "", 487, 13, "シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 488, 13, "シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 13, 0, "", 489, 13, "…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 490, 14, "3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 491, 14, "記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 492, 14, "うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 36, 0, "", 493, 14, "ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 494, 14, "みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 495, 14, "シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 37, 0, "", 496, 14, "はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", 105901, 1, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 497, 14, "ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", 106001, 0, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 498, 14, "へ、へぇ…", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 499, 14, "期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 500, 14, "ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 501, 14, "それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", 106401, 2, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 502, 15, "それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 42, 0, "", 503, 15, "祝！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 38, 0, "", 504, 15, "3.5周年！", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 505, 15, "おめでとうございます！", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 14, 0, "", 506, 15, "この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 15, 0, "", 507, 15, "ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", 190801, 2, 80005, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 508, 15, "感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 509, 15, "なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 43, 0, "", 510, 15, "えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 511, 15, "でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", 106001, 1, 80005, 0, "キャル");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 44, 0, "", 512, 15, "ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 45, 0, "", 513, 15, "最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", 106401, 0, 80005, 0, "シェフィ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 39, 0, "", 514, 15, "では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 40, 0, "", 515, 15, "ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 41, 0, "", 516, 15, "わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", 105901, 4, 80005, 0, "コッコロ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 45, 0, "", 517, 15, "それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", 105801, 3, 80005, 0, "ペコリーヌ");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 46, 1, "105901,42,106001,45,106401,46,190801,16", 518, 15, "これからも\nよろしくおねがいします！", 105801, 4, 80005, 0, "みんな");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 519, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, 1, 60003, 1, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 520, 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 521, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 522, 0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 523, 0, "今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 524, 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 0, 2, 60003, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 525, 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 526, 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 527, 0, "今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 528, 0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 529, 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 0, 2, 60003, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 530, 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 531, 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 532, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 533, 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 534, 0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 535, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 536, 0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 0, 2, 60003, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 537, 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 538, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 539, 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 540, 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 541, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 542, 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 0, 2, 60003, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 543, 0, "今日の運勢は小吉！　無理は禁物、お家で静かにしていましょう　プロぼっちの私が、お家での過ごし方……教えてあげましょうか？", 0, 2, 60003, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, 0, "", 544, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, 3, 60003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, 0, "", 545, 7, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, 3, 60003, 0, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, 0, "", 546, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, 1, 60004, 1, "カリン");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 547, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 548, 0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 549, 0, "今日の運勢は姫吉！　宴でも開きたくなるほどの絶対幸運！\nイメチェンでもしてみるのはどうだ？　ぴょんぴょん、なんてな♪", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 550, 0, "今日の運勢は姫吉！　ずっと祈り続けていた願いが叶うかも！\nきっとあんたならたどり着けるわ、ハッピーエンドのその先に", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (1, 0, 0, "", 551, 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 552, 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 553, 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 0, 2, 60004, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 554, 0, "今日の運勢は大吉！　ラッキーワードは「ぴょんぴょん♪」\nおっきな声で一緒に言ってみよ～♪　うさぎさんぴょんぴょ～ん♪", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 555, 0, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (2, 0, 0, "", 556, 0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 557, 0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 558, 0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 0, 2, 60004, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 559, 0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 560, 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 561, 0, "今日の運勢は中吉！　健康に気を遣って気持ちのいい一年を！\n体に不調があるときは遠慮なく言いなさい、隅々まで調べてあげる", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 562, 0, "今日の運勢は中吉！　歌を口ずさみ、幸運を呼び込もう！\n幸運になれるかは分からないけど……一緒に、歌いましょ？", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (3, 0, 0, "", 563, 0, "今日の運勢は中吉！　誰かに尽くすことで掴める幸せもあるかも？\n人事を尽くして天命を待つ！　さ、年始もバリバリ働きますわよ♪", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 564, 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 565, 0, "今日の運勢は小吉！　無理は禁物、お家で静かにしていましょう　プロぼっちの私が、お家での過ごし方……教えてあげましょうか？", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 566, 0, "今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 567, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 0, 2, 60004, 2, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 568, 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 569, 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 0, 2, 60004, 1, "");
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (4, 0, 0, "", 570, 0, "今日の運勢は小吉！　小さな勇気で踏み出す一歩が大事！\n遠くから見てるだけじゃダメ。今日は、少しだけ近づいてみます！", 0, 2, 60004, 2, "");
